package com.andye.warmod.radar.client;import com.andye.warmod.radar.RadarTerrainTile;import java.util.*;public final class ClientRadarTerrainCache{private final Map<Long,RadarTerrainTile> tiles=new LinkedHashMap<>(256,.75F,true){protected boolean removeEldestEntry(Map.Entry<Long,RadarTerrainTile> e){return size()>8192;}};public void putAll(Collection<RadarTerrainTile> values){for(RadarTerrainTile t:values)tiles.put(t.key(),t);}public Collection<RadarTerrainTile> values(){return List.copyOf(tiles.values());}public int size(){return tiles.size();}public void clear(){tiles.clear();}}
